def early_stop_epoch(val_losses, patience):
    best = float('inf')
    wait = 0
    for i, loss in enumerate(val_losses):
        if loss < best:
            best = loss
            wait = 0
        else:
            wait += 1
            if wait >= patience:
                return i
    return len(val_losses) - 1

